window.openEmployeeAccountsV359=function(id,bu,name){window.__v359AccountBuOverride=Number(bu||0);const fn=window.openCounterpartyAccountsV338||window.managePayeeAccountsV330;if(typeof fn!=='function')return toast('Account manager is unavailable.');fn('employee',Number(id),name||'Employee')};
const oldClose=window.v338CloseAccountManager;if(typeof oldClose==='function')window.v338CloseAccountManager=function(){const r=oldClose.apply(this,arguments);const id=window.__v290EmployeeDetail?.employee?.id;window.__v359AccountBuOverride=0;if(id)setTimeout(()=>employeeProfileV359(id,'accounts').catch?.(()=>{}),60);return r};
window.recoveryMethodChangedV359=function(f){if(!f)return;const m=f.recovery_method?.value||'Manual',value=f.querySelector('[data-v359-value]'),inst=f.querySelector('[data-v359-installments]');if(value)value.style.display=['Fixed Amount','Percentage of Salary'].includes(m)?'block':'none';if(inst)inst.style.display=m==='Fixed Payrolls'?'block':'none'};

window.reviewEmployeeAccountRequestV359=async function(requestId,employeeId,decision){const review_note=prompt(decision==='Approve'?'Approval note (optional)':'Reason for rejection');if(review_note===null)return;try{await api('/api/payroll/account-change-requests/'+requestId+'/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,review_note})});toast('Employee payment account request '+(decision==='Approve'?'approved.':'rejected.'));await employeeProfileV359(employeeId,'accounts')}catch(x){toast(x.message)}};
window.saveRecoveryTermsV359=async function(ev,id){ev.preventDefault();const f=ev.target,d=Object.fromEntries(new FormData(f));d.recovery_value=n(d.recovery_value);d.installments_total=Number(d.installments_total||0);try{await api('/api/payroll/employees/'+id+'/recovery-terms',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});toast('Advance recovery terms updated.');await employeeProfileV359(id,'advances')}catch(x){toast(x.message)}};

window.employeeAdvanceV29=window.employeeAdvanceV359=async function(id){try{const [d,pas,accounts]=await Promise.all([api('/api/payroll/employees/'+id),api('/api/accounting/payment-accounts'),api('/api/v338/payee-accounts?'+new URLSearchParams({business_unit_id:String(window.__v290EmployeeDetail?.employee?.business_unit_id||selectedUnitId||me?.business_unit_id||''),entity_type:'employee',entity_id:String(id),include_archived:'0'}))]),e=d.employee,def=accounts.find(a=>Number(a.is_default))||accounts[0];modal(`<div class="section-title"><div><h2>${esc(t('Give Advance'))}</h2><div class="muted">Creates one Finance Money Out record. Accounting is prepared from that Finance record after verification.</div></div><button class="btn" onclick="closeModal();employeeProfileV359(${id},'advances')">✕</button></div>${!accounts.length?`<div class="v359-warning">No employee receiving account is saved. <button class="btn small" type="button" onclick="openEmployeeAccountsV359(${id},${Number(e.business_unit_id)},'${esc(String(e.name).replace(/'/g,"\\'"))}')">Add / Manage Accounts</button></div>`:''}<form onsubmit="saveEmployeeAdvanceV359(event,${id})" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>${esc(t('Amount'))} *</label><input name="original_amount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>${esc(t('Currency'))}</label><select name="currency"><option>KRW</option><option>USD</option><option>PKR</option></select></div><div class="field"><label>FX Rate to KRW</label><input name="fx_rate" type="number" step="0.000001" value="1"></div><div class="field"><label>${esc(t('Date'))} *</label><input name="advance_date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>${esc(t('Payment Method'))}</label><select name="payment_method"><option>Bank</option><option>Cash</option></select></div><div class="field"><label>Paid From — Company Account *</label><select name="payment_account_id" required>${typeof paymentAccountOptionsV29==='function'?paymentAccountOptionsV29(pas,e.payment_account_id,e.business_unit_id):pas.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Paid To — Employee Account *</label><select name="receiver_account_id" required><option value="">Select employee account</option>${accounts.map(a=>`<option value="${a.id}" ${def&&Number(a.id)===Number(def.id)?'selected':''}>${esc(a.label||'Account')} · ${esc(a.bank_name||a.method_type||'')} · ${esc(a.currency||'')} ${esc(a.account_number_masked||'')}</option>`).join('')}</select></div><div class="field"><label>${esc(t('Reference'))}</label><input name="reference" placeholder="Required for non-cash payment"></div><div class="field"><label>${esc(t('Employee Advance Receipt / Evidence'))} *</label><input name="evidence" type="file" required></div></div><div class="field"><label>${esc(t('Notes'))}</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal();employeeProfileV359(${id},'advances')">${esc(t('Cancel'))}</button><button class="btn primary">${esc(t('Review & Confirm'))}</button></div></form>`,'wide')}catch(x){toast(x.message)}};
